from review import card,save,DATE,DIRECTORY,write
import json
def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

i='TCS-2277';_,c=card(i);refs=c['references'];refs[0]['locator']='CCC 2024, article 14: Section 7.2, equation (7.3), Conjecture 7.3 and Example 7.4 read. The target is Euclidean distance to the unique minimizer, not an objective-value error.'
refs.append(dict(id='interior_point',title='Interior-Point Methods on Manifolds: Theory and Applications',authors='Hiroshi Hirai, Harold Nieuwboer, Michael Walter',year=2026,url='https://doi.org/10.1007/s10208-026-09756-8',locator='Published 7 July 2026. Abstract and Section 1.4, especially Theorem 1.8, read on the publisher page. The Kempf–Ness guarantee is objective-value approximation on a bounded domain, not Euclidean approximation of this unique minimizer.'))
save(i,dict(title='High-precision approximation of a log-sum-exp minimizer',formal='Is there a polynomial-time algorithm that, given integer vectors ω_1,…,ω_n∈Z^d with 0 in the full-dimensional interior of their convex hull, nonzero Gaussian rationals v_1,…,v_n and a precision p≥1, outputs x∈Q^d with ||x−x*||₂<2^{−p}, where x* is the unique minimizer of f(x)=log(Σ_{i=1}^n |v_i|² exp(ω_i·x))? The time must be polynomial in the input dimensions, coefficient bit lengths and p.',definitions='Let M∈Z^{d×n} have columns ω_i, and let P=conv{ω_1,…,ω_n}={Σ_i a_iω_i: a_i≥0, Σ_i a_i=1}. The promise 0∈int(P) uses interior in R^d, not relative interior in a smaller affine space. A Gaussian rational v_i has the form a_i+b_i√(−1), with a_i,b_i∈Q; v_i≠0 ensures q_i=|v_i|²=a_i²+b_i²>0. The logarithm and exponential in f are the real natural logarithm and exponential. Under the promise, f is strictly convex, attains its minimum, and has exactly one minimizer x*∈R^d. Integers and rational numerators/denominators are encoded in binary. If B and b are the respective total encoding lengths of M and v, the target bit complexity is poly(d,n,B,b,p), including the rational output. Precision is supplied as an integer p and the running time is polynomial in its numerical value. This standard dyadic-accuracy convention spells out the source’s log(1/ε) dependence for ε=2^{−p}; a general binary rational accuracy request also incurs the cost of reading that request. No bound on a Hessian condition number or on the numerical magnitudes of the integer weights is an additional promise.',question_type='yes_no',answer_criterion='Give an algorithm with the stated bit-complexity and Euclidean error guarantee on every promised input, or establish an obstruction to this guarantee. A small value of f(x)−min f, a small gradient, or convergence without the polynomial dependence on coefficient bit lengths and requested precision does not suffice.',context_blocks=[b('The target is a location, not just a low value','Two points can have almost identical objective values while remaining far apart in a very flat direction. This card asks for the actual coordinates of the unique minimum to a prescribed Euclidean accuracy.'),b('Ordinary approximate minimization is already available','The source cites polynomial-time algorithms producing points of nearly optimal objective value. Example 7.4 shows a family where a point remains distance one from x* despite a value gap doubly exponentially small in the coefficient encoding length.', 'primary'),b('Binary encoding makes large weights inexpensive to describe','An integer exponent weight can be exponentially large relative to its number of bits. An algorithm polynomial in that numerical weight would not provide the requested polynomial bit complexity.'),b('The invariant-theory setting explains the objective','For a diagonal torus action, the squared norm after scaling is Σ_i |v_i|² exp(ω_i·x). Its minimizing location specifies a distinguished scaling associated with the Kempf–Ness orbit. The numerical formulation above states the target without requiring group-action notation.', 'primary')],why='Separates efficient approximation of convex objective values from efficient recovery of minimizers, with consequences for canonical scaling and orbit comparison in invariant theory.',progress=[dict(date='2024',text='The source states Conjecture 7.3 and gives an explicit separation between very small value error and small distance to the minimizer.',citation='primary'),dict(date='2026-07-07',text='The manifold interior-point theorem gives objective-value guarantees for Kempf–Ness functions; its stated conclusion does not resolve this point-approximation problem.',citation='interior_point')],references=refs,status='source_open',status_note='Full conjecture, coordinate normalization and flatness example checked, together with the source version record and the 2026 interior-point theorem. No polynomial-bit-time Euclidean minimizer approximation was located through 12 September 2026.',model_self_contained=True,requires_context=False,importance=imp(c,'A basic precision distinction in convex optimization and computational invariant theory.'),review_note='Recovered the missing rational output and logarithmic accuracy dependence. Defined the objective and full-dimensional interior promise directly, and used a dyadic precision parameter to make the bit-cost convention explicit.',working_summary=sm(['The input defines a strictly convex logarithm of a weighted sum of exponentials.','Its minimum exists and is unique, but the question asks to locate that minimum accurately.','The required running time is polynomial in coefficient bit lengths and the number of desired accuracy bits.','Existing small-objective-error guarantees can leave the point far from the minimizer.','The related 2026 optimization theorem still supplies a value guarantee rather than this distance guarantee.'],['primary','interior_point'])),notes=['Recovered the exact log-sum-exp objective, interior promise and unique minimizer.','Specified rational output, Euclidean error and binary input/precision complexity.','Distinguished objective-value optimization from minimizer approximation, including the 2026 result.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2405.15368'])

i='TCS-2281';_,c=card(i);refs=c['references'];refs[0]['locator']='DISC 2024, article 25: CONGEST and FO conventions, bounded-expansion discussion and the final question on PDF p. 16 read. It restates the Nešetřil–Ossona de Mendez local-FO vertex-marking question.'
refs.extend([
dict(id='solution',title='What Can Be Computed Locally Revisited — First-Order Logic on Sparse Graphs in Distributed Computing',authors='Lélia Blin, Fedor V. Fomin, Pierre Fraigniaud, Sylvain Gay, Petr A. Golovach, Pedro Montealegre, Ivan Rapaport, Ioan Todinca',year=2026,url='https://arxiv.org/abs/2411.14825v3',locator='Version 3, 4 February 2026: Question 1.3, Theorems 1.4 and 4.1, Section 3.3 expansion convention and initial-information assumptions read. Theorem 4.1 explicitly supplies deterministic simultaneous vertex marking in O(log n) CONGEST rounds.'),
dict(id='publication',title='What Can Be Computed Locally Revisited: First-Order Logic on Sparse Graphs in Distributed Computing — STOC publication',authors='Lélia Blin, Fedor V. Fomin, Pierre Fraigniaud, Sylvain Gay, Petr A. Golovach, Pedro Montealegre, Ivan Rapaport, Ioan Todinca',year=2026,url='https://doi.org/10.1145/3798129.3800849',locator='STOC 2026, pp. 1397–1408. Official accepted-paper list and author-institution publication record checked; full theorem read in reference solution.')])
save(i,dict(title='Local first-order vertex marking in logarithmically many CONGEST rounds',status='resolved',formal='Historical question, resolved positively: for every fixed local first-order graph formula φ(x) and every fixed graph class C of bounded expansion, can a deterministic CONGEST algorithm mark exactly the vertices v satisfying G⊨φ(v) in O(log n) rounds, simultaneously for every n-vertex input graph G∈C? The constructive formulation uses the class’s fixed computable expansion bound.',definitions='The network is a finite connected undirected simple graph G=(V,E), n=|V|. Nodes have distinct O(log n)-bit identifiers, communication ports and a common polynomial upper bound on n. They communicate synchronously, with O(log n) bits per edge in each direction per round, and unrestricted local computation. No graph decomposition is supplied. A first-order formula uses vertex variables, equality, adjacency, Boolean operations and vertex quantifiers. Here φ has one free variable x. It is local if some fixed radius r makes its truth at v depend only on the rooted induced neighborhood of all vertices at graph distance at most r from v. The formula and r are fixed independently of n. A graph class has bounded expansion if for every integer s≥0 there is a constant b_s bounding the average degree of every s-shallow minor of every graph in the class. Such a minor is formed by contracting pairwise vertex-disjoint connected subgraphs of radius at most s, with optional vertex/edge deletions and with parallel edges and loops suppressed. The constructive source assumes a computable bound as a function of s; the class and its bound are fixed, not arbitrary input. The required output at each node v is a Boolean bit equal to the truth value of φ(v). The hidden round constant may depend on φ and C, but not on n, the graph or the identifiers.',question_type='yes_no',answer_criterion='The affirmative result is Theorem 1.4, formally Theorem 4.1, of the full version published at STOC 2026. It gives exactly the required deterministic simultaneous marking algorithm, and additionally permits a fixed finite set of unary vertex labels.',context_blocks=[b('Logical locality does not remove bandwidth limits','A formula may depend on only a small-radius neighborhood even when that neighborhood contains many vertices. Collecting the entire neighborhood can overload O(log n)-bit links, so constant logical radius does not automatically yield a fast CONGEST algorithm.'),b('Every vertex needs its own answer','For example, φ(x) can say that x belongs to a triangle. The task is to identify every vertex with that property, not merely to have some node detect that a triangle exists.'),b('The graph-class promise is essential','Bounded expansion includes planar graphs, bounded-degree graphs and classes excluding a fixed minor. Bounding degeneracy alone is weaker and does not give the same general theorem.', 'solution'),b('The later theorem resolves the exact old question','The STOC paper explicitly restates the question cited by the 2024 card and answers it with deterministic O(log n) vertex marking. Its separate theorem for unrestricted FO formulas costs O(D+log n), where D is the diameter; the local target here has no D term.', 'solution')],why='Shows that logical locality can be translated into efficient distributed computation despite narrow communication links throughout a broad family of sparse graph classes.',progress=[dict(date='2024',text='The DISC paper restates the local-FO marking question attributed to Nešetřil and Ossona de Mendez.',citation='primary'),dict(date='2026-02-04',text='The checked full version states the affirmative deterministic O(log n) result as Theorems 1.4 and 4.1.',citation='solution'),dict(date='2026',text='The result is published at STOC 2026, pp. 1397–1408.',citation='publication')],references=refs,status_note='Resolved by Blin, Fomin, Fraigniaud, Gay, Golovach, Montealegre, Rapaport and Todinca, STOC 2026. The exact historical question, local formula, bounded-expansion convention, node information and Theorem 4.1’s simultaneous deterministic output were matched. This is published-theorem/model verification, not an independent proof audit or proof-assistant certificate.',model_self_contained=True,requires_context=False,importance=imp(c,'A distributed algorithmic meta-theorem connecting logical locality to bounded-bandwidth computation on sparse graphs.'),review_note='Restored the missing bounded-expansion scope and per-vertex output. Matched the question to the subsequent full theorem and publication, keeping local O(log n) marking separate from global FO decision.',working_summary=sm(['A fixed local first-order formula asks a question about the neighborhood of each graph vertex.','The historical problem was to mark all satisfying vertices using only short messages along graph edges.','Blin and coauthors give a deterministic O(log n)-round algorithm for every fixed bounded-expansion class.','Their theorem answers the exact question restated in the 2024 source and was published at STOC 2026.','The global first-order model-checking extension has an additional diameter term and is a separate result.'],['primary','solution','publication'])),notes=['Recovered bounded expansion, CONGEST bandwidth, local FO semantics and simultaneous vertex marking.','Checked Theorem 4.1 and the STOC 2026 publication against the original question.','Marked the historical question resolved and separated it from global FO decision.'],checked_sources=[r['url'] for r in refs]+['https://acm-stoc.org/stoc2026/accepted-papers.html','https://pure.uai.cl/en/publications/what-can-be-computed-locally-revisited-first-order-logic-on-spars/'])
qpath=DIRECTORY/'queue.json';q=json.loads(qpath.read_text());_,c=card(i)
if not any(x['id']==i for x in q['dispositions']):q['dispositions'].append(dict(id=i,title=c['title'],state='resolved',reason=c['status_note'],card='data/cards/'+i+'.json'))
write(qpath,q)
